import{_ as a,o as i,c as n,a0 as l}from"./chunks/framework.DhQjJcnt.js";const g=JSON.parse('{"title":"Skill: /grill-bqa","description":"","frontmatter":{},"headers":[],"relativePath":"references/skills/grill-bqa.md","filePath":"references/skills/grill-bqa.md"}'),o={name:"references/skills/grill-bqa.md"};function t(c,e,r,d,h,s){return i(),n("div",null,[...e[0]||(e[0]=[l('<h1 id="skill-grill-bqa" tabindex="-1">Skill: <code>/grill-bqa</code> <a class="header-anchor" href="#skill-grill-bqa" aria-label="Permalink to &quot;Skill: `/grill-bqa`&quot;">​</a></h1><h2 id="ten" tabindex="-1">Tên <a class="header-anchor" href="#ten" aria-label="Permalink to &quot;Tên&quot;">​</a></h2><p><code>grill-bqa</code></p><h2 id="cach-dung-command-trigger" tabindex="-1">Cách dùng (Command/Trigger) <a class="header-anchor" href="#cach-dung-command-trigger" aria-label="Permalink to &quot;Cách dùng (Command/Trigger)&quot;">​</a></h2><ul><li>Gọi qua slash command: <code>/grill-bqa &lt;page-id/slug&gt;</code></li><li>Tự động trigger sau khi kỹ năng <code>/spec</code> hoàn thành hoặc chuyển giao từ <code>/grill</code>.</li></ul><h2 id="input-du-lieu-đau-vao" tabindex="-1">Input (Dữ liệu đầu vào) <a class="header-anchor" href="#input-du-lieu-đau-vao" aria-label="Permalink to &quot;Input (Dữ liệu đầu vào)&quot;">​</a></h2><ul><li>File <code>*.bundle.yaml</code> chứa thiết kế UI và logic.</li><li>File trung gian <code>ir/design.yaml</code> và <code>ir/spec.yaml</code> sinh ra từ bundle.</li><li>Yêu cầu User Prompt ban đầu (nếu có bổ sung).</li></ul><h2 id="output-ket-qua-mong-đoi" tabindex="-1">Output (Kết quả mong đợi) <a class="header-anchor" href="#output-ket-qua-mong-đoi" aria-label="Permalink to &quot;Output (Kết quả mong đợi)&quot;">​</a></h2><ul><li>Các file <code>*.bundle.yaml</code> được làm sạch, bổ sung và chuẩn hóa về mặt Business và UI.</li><li>File QA Tech Debt (<code>qa/open/QA-&lt;page-id&gt;-NNNN.yaml</code>) nếu có thông tin chưa chốt.</li><li>Trạng thái <code>grillStatus.bqaFacts: done</code> và <code>grillStatus.bqaOpen: done</code>.</li></ul><h2 id="description-y-nghia" tabindex="-1">Description / Ý nghĩa <a class="header-anchor" href="#description-y-nghia" aria-label="Permalink to &quot;Description / Ý nghĩa&quot;">​</a></h2><ul><li>Chuyên dùng để Review và Validate đặc tả (Spec) từ góc nhìn của Business Analyst (BA) / QA UI. Không soi các thẻ kỹ thuật (<code>#gen</code>, <code>codegen.profile</code>).</li><li>Kiểm tra tính hợp lý của UX/UI: So sánh layout, copy, purpose với các template UI chung. Đảm bảo mô tả theo ngôn ngữ Stakeholder.</li><li>Bắt buộc kiểm định: Các lỗi luồng UI (UI Error Handling Flows). Mọi action gọi API phải mô tả rõ 3 trạng thái: <ul><li><code>onSuccess</code>: Trạng thái thành công.</li><li><code>onCommonError</code>: Báo lỗi hệ thống (401, 500) hoặc ghi đè (<code>override: true</code>).</li><li><code>onSpecificError</code>: Báo lỗi validation (422), không tìm thấy (404), IDOR (403), hoặc trùng lặp (409).</li></ul></li><li>Quá trình xử lý diễn ra qua 2 bước: <ul><li><strong>Step A:</strong> Fact-lock (Khóa logic chuẩn hóa dữ liệu cũ, không được dùng Wizard hỏi ở bước này).</li><li><strong>Step B:</strong> Member Wizard (Tung form AskQuestion cho các khoảng trống thông tin).</li></ul></li></ul><h2 id="cac-skill-lien-quan" tabindex="-1">Các Skill liên quan <a class="header-anchor" href="#cac-skill-lien-quan" aria-label="Permalink to &quot;Các Skill liên quan&quot;">​</a></h2><ul><li><strong>Trước đó:</strong> Nhận đầu vào từ <code>/spec</code> hoặc <code>/grill</code>.</li><li><strong>Sau đó:</strong> Chuyển giao sang <code>/grill-dev</code> để soi chiếu góc nhìn lập trình viên (Codegen/Tech).</li></ul><h2 id="chu-y-quan-trong" tabindex="-1">Chú ý quan trọng <a class="header-anchor" href="#chu-y-quan-trong" aria-label="Permalink to &quot;Chú ý quan trọng&quot;">​</a></h2><ul><li><strong>Luật AskQuestion Tech Debt:</strong> Trong Step B (Member Wizard), các lựa chọn đưa ra hỏi phải bao gồm option <code>&quot;Log as Tech Debt&quot;</code>. Nếu user chọn option này, hệ thống sẽ đẩy thẳng vướng mắc vào file QA Inbox (<code>qa-inbox.md</code>) thay vì đoán mò.</li><li>Không đọc các file Markdown được render (<code>*.md</code>), chỉ đọc <code>ir/design.yaml</code> và Bundle gốc.</li><li>Nếu chưa chạy xong <code>bqaFacts: done</code> thì tuyệt đối không được mở Step B (Wizard).</li></ul><hr><h2 id="example-prompt-mau-goi" tabindex="-1">Example prompt (mẫu gọi) <a class="header-anchor" href="#example-prompt-mau-goi" aria-label="Permalink to &quot;Example prompt (mẫu gọi)&quot;">​</a></h2><p><strong>Quy tắc:</strong> một session = một command · chat mới khi đổi phase · cập nhật <code>.harness/progress.md</code> nếu có.</p><p><strong>Khi nào:</strong> Gọi khi scope khớp mô tả skill ở trên.</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/grill-bqa</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>Surface: {admin-web} · Module: {CMP-…} · Scope: {mô tả ngắn}</span></span></code></pre></div>',20)])])}const p=a(o,[["render",t]]);export{g as __pageData,p as default};
